"var w = $('#' + id);
var game = w.closest('.rl_game');

var RED_NUMBERS = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];

function numColor(n) {
    if (n === 0) return 'green';
    return RED_NUMBERS.indexOf(n) >= 0 ? 'red' : 'black';
}

function cellWon(betKey) {
    if (!result) return false;
    var n = result.number, c = result.color;
    if (betKey === 'red')    return c === 'red';
    if (betKey === 'black')  return c === 'black';
    if (betKey === 'odd')    return n > 0 && n % 2 === 1;
    if (betKey === 'even')   return n > 0 && n % 2 === 0;
    if (betKey === 'low')    return n >= 1 && n <= 18;
    if (betKey === 'high')   return n >= 19 && n <= 36;
    if (betKey === 'dozen1') return n >= 1  && n <= 12;
    if (betKey === 'dozen2') return n >= 13 && n <= 24;
    if (betKey === 'dozen3') return n >= 25 && n <= 36;
    if (betKey === 'col1')   return n > 0 && n % 3 === 0;
    if (betKey === 'col2')   return n > 0 && n % 3 === 2;
    if (betKey === 'col3')   return n > 0 && n % 3 === 1;
    return parseInt(betKey) === n;
}

if (phase === 'spinning') {
    w.append($('<div class="rl-spinning">Spinning…</div>'));
    return;
}

var clickable = phase === 'betting' || phase === 'result';

function makeCell(betKey, label, colorCls, gridCol, gridRow, colSpan, rowSpan) {
    colSpan = colSpan || 1;
    rowSpan = rowSpan || 1;
    var isResultNum = result && !isNaN(parseInt(betKey)) && parseInt(betKey) === result.number;
    var won = bets[betKey] && cellWon(betKey);
    var cls = 'rl-cell ' + colorCls;
    if (isResultNum) cls += ' rl-result-num';
    if (won) cls += ' rl-won';
    if (clickable && betKey !== null) cls += ' rl-clickable';

    var div = $('<div></div>').attr('class', cls).text(label);
    div.css({ 'grid-column': gridCol + ' / span ' + colSpan, 'grid-row': gridRow + ' / span ' + rowSpan });

    if (bets[betKey]) {
        div.append($('<span class="rl-bet-amt">$' + bets[betKey] + '</span>'));
    }
    if (clickable && betKey !== null) {
        div.on('click', function() { game.trigger('rl_place_bet', [betKey]); });
    }
    return div;
}

var grid = $('<div class="rl-grid"></div>');

// 0 cell: col 1, rows 1-3
grid.append(makeCell('0', '0', 'rl-green', 1, 1, 1, 3));

// Numbers 1-36
// Layout: row 1=multiples of 3, row 2=n%3===2, row 3=n%3===1
// Grid col = ceil(n/3) + 1  (cols 2-13)
for (var n = 1; n <= 36; n++) {
    var gridRow = (n % 3 === 0) ? 1 : (n % 3 === 2) ? 2 : 3;
    var gridCol = Math.ceil(n / 3) + 1;
    var color = numColor(n);
    grid.append(makeCell(String(n), n, 'rl-' + color, gridCol, gridRow, 1, 1));
}

// Column bets: grid col 14, rows 1-3
grid.append(makeCell('col1', '2:1', 'rl-outside', 14, 1, 1, 1));
grid.append(makeCell('col2', '2:1', 'rl-outside', 14, 2, 1, 1));
grid.append(makeCell('col3', '2:1', 'rl-outside', 14, 3, 1, 1));

// Dozen bets: row 4, cols 2-5 / 6-9 / 10-13
grid.append(makeCell('dozen1', '1st 12', 'rl-outside', 2,  4, 4, 1));
grid.append(makeCell('dozen2', '2nd 12', 'rl-outside', 6,  4, 4, 1));
grid.append(makeCell('dozen3', '3rd 12', 'rl-outside', 10, 4, 4, 1));

// Outside bets: row 5, pairs of cols from 2-13
grid.append(makeCell('low',   '1-18',  'rl-outside', 2,  5, 2, 1));
grid.append(makeCell('even',  'EVEN',  'rl-outside', 4,  5, 2, 1));
grid.append(makeCell('red',   'RED',   'rl-red',     6,  5, 2, 1));
grid.append(makeCell('black', 'BLACK', 'rl-black',   8,  5, 2, 1));
grid.append(makeCell('odd',   'ODD',   'rl-outside', 10, 5, 2, 1));
grid.append(makeCell('high',  '19-36', 'rl-outside', 12, 5, 2, 1));

w.append(grid);"

