"var w = $('#' + id);

var RED_NUMBERS = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];

function numColor(n) {
    if (n === 0) return 'green';
    return RED_NUMBERS.indexOf(n) >= 0 ? 'red' : 'black';
}

var state = {
    bankroll: 1000,
    bets: {},
    selectedChip: 25,
    result: null,
    phase: 'betting',
    message: ''
};

function totalBet() {
    return Object.keys(state.bets).reduce(function(s, k) { return s + state.bets[k]; }, 0);
}

function calcPayout(betKey, num, color) {
    if (betKey === 'red')    return color === 'red'   ? 1 : 0;
    if (betKey === 'black')  return color === 'black' ? 1 : 0;
    if (betKey === 'odd')    return num > 0 && num % 2 === 1 ? 1 : 0;
    if (betKey === 'even')   return num > 0 && num % 2 === 0 ? 1 : 0;
    if (betKey === 'low')    return num >= 1 && num <= 18 ? 1 : 0;
    if (betKey === 'high')   return num >= 19 && num <= 36 ? 1 : 0;
    if (betKey === 'dozen1') return num >= 1  && num <= 12 ? 2 : 0;
    if (betKey === 'dozen2') return num >= 13 && num <= 24 ? 2 : 0;
    if (betKey === 'dozen3') return num >= 25 && num <= 36 ? 2 : 0;
    if (betKey === 'col1')   return num > 0 && num % 3 === 0 ? 2 : 0;
    if (betKey === 'col2')   return num > 0 && num % 3 === 2 ? 2 : 0;
    if (betKey === 'col3')   return num > 0 && num % 3 === 1 ? 2 : 0;
    return parseInt(betKey) === num ? 35 : 0;
}

function spin() {
    if (totalBet() === 0) { state.message = 'Place a bet first!'; render(); return; }
    state.phase = 'spinning';
    render();
    setTimeout(function() {
        var num = Math.floor(Math.random() * 37);
        var color = numColor(num);
        state.result = { number: num, color: color };

        var totalWagered = totalBet();
        var totalReturn = 0;
        Object.keys(state.bets).forEach(function(k) {
            var amt = state.bets[k];
            var mult = calcPayout(k, num, color);
            if (mult > 0) totalReturn += amt * (1 + mult);
        });

        var net = totalReturn - totalWagered;
        state.bankroll += net;

        if (net > 0) {
            state.message = '★ ' + num + ' ' + color.toUpperCase() + '! You win $' + net + '!';
        } else if (net < 0) {
            state.message = num + ' ' + color.toUpperCase() + '. You lose $' + Math.abs(net) + '.';
        } else {
            state.message = num + ' ' + color.toUpperCase() + '. Push.';
        }
        if (state.bankroll <= 0) { state.bankroll = 1000; state.message += ' Bankroll reset.'; }

        state.phase = 'result';
        state.bets = {};
        render();
    }, 1200);
}

function render() {
    w.empty();
    w.append(widget('rl:rl_board', {
        bets: state.bets,
        phase: state.phase,
        result: state.result
    }));
    w.append(widget('rl:rl_controls', {
        bankroll: state.bankroll,
        selectedChip: state.selectedChip,
        totalBet: totalBet(),
        phase: state.phase,
        message: state.message
    }));
}

w.on('rl_place_bet', function(e, betKey) {
    if (state.phase === 'spinning') return;
    if (state.phase === 'result') {
        state.phase = 'betting';
        state.result = null;
        state.message = '';
    }
    var available = state.bankroll - totalBet();
    if (state.selectedChip > available) return;
    state.bets[betKey] = (state.bets[betKey] || 0) + state.selectedChip;
    render();
});

w.on('rl_clear_bets', function() {
    if (state.phase === 'spinning') return;
    state.bets = {};
    state.phase = 'betting';
    state.result = null;
    state.message = '';
    render();
});

w.on('rl_spin', function() { spin(); });

w.on('rl_select_chip', function(e, amount) {
    state.selectedChip = amount;
    render();
});

render();"

