"var w = $('#' + id);

// Persist wheel state across re-renders
if (window._rl_wheel_cancel) { window._rl_wheel_cancel(); }
if (!window._rl_wheel) { window._rl_wheel = { angle: 0, ballAngle: -Math.PI / 2, ballRadius: 101 }; }
var ws = window._rl_wheel;

var WHEEL = [0,32,15,19,4,21,2,25,17,34,6,27,13,36,11,30,8,23,10,5,24,16,33,1,20,14,31,9,22,18,29,7,28,12,35,3,26];
var RED   = [1,3,5,7,9,12,14,16,18,19,21,23,25,27,30,32,34,36];
var N     = 37;
var SLOT  = 2 * Math.PI / N;

var SIZE    = 260;
var CX      = SIZE / 2;
var CY      = SIZE / 2;
var RO      = 110;
var RI      = 65;
var BALL_R  = RO - 9;
var POCKET_R = Math.round((RO + RI) / 2);

var canvas = document.createElement('canvas');
canvas.width = SIZE;
canvas.height = SIZE;
canvas.style.cssText = 'display:block;margin:0 auto;';
w.append(canvas);
var ctx = canvas.getContext('2d');

function pocketColor(n) {
    if (n === 0) return '#1e8449';
    return RED.indexOf(n) >= 0 ? '#c0392b' : '#1a1a1a';
}

function draw() {
    ctx.clearRect(0, 0, SIZE, SIZE);

    // Wooden outer rim
    ctx.beginPath();
    ctx.arc(CX, CY, RO + 13, 0, 2 * Math.PI);
    ctx.fillStyle = '#3d2008';
    ctx.fill();
    ctx.strokeStyle = '#b8860b';
    ctx.lineWidth = 3;
    ctx.stroke();

    // Pockets (annular segments)
    for (var i = 0; i < N; i++) {
        var a0 = ws.angle + i * SLOT - SLOT / 2;
        var a1 = a0 + SLOT;
        ctx.beginPath();
        ctx.arc(CX, CY, RO, a0, a1);
        ctx.arc(CX, CY, RI, a1, a0, true);
        ctx.closePath();
        ctx.fillStyle = pocketColor(WHEEL[i]);
        ctx.fill();
        ctx.strokeStyle = 'rgba(184,134,11,0.5)';
        ctx.lineWidth = 0.5;
        ctx.stroke();
    }

    // Numbers
    for (var i = 0; i < N; i++) {
        var midA = ws.angle + i * SLOT;
        var nr = (RO + RI) / 2;
        ctx.save();
        ctx.translate(CX + nr * Math.cos(midA), CY + nr * Math.sin(midA));
        ctx.rotate(midA + Math.PI / 2);
        ctx.fillStyle = 'white';
        ctx.font = 'bold 7px sans-serif';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(String(WHEEL[i]), 0, 0);
        ctx.restore();
    }

    // Inner bowl
    ctx.beginPath();
    ctx.arc(CX, CY, RI - 2, 0, 2 * Math.PI);
    var bowlGrad = ctx.createRadialGradient(CX, CY - 20, 5, CX, CY, RI);
    bowlGrad.addColorStop(0, '#3d2008');
    bowlGrad.addColorStop(1, '#1a0f0a');
    ctx.fillStyle = bowlGrad;
    ctx.fill();
    ctx.strokeStyle = '#b8860b';
    ctx.lineWidth = 2;
    ctx.stroke();

    // Center hub
    ctx.beginPath();
    ctx.arc(CX, CY, 16, 0, 2 * Math.PI);
    ctx.fillStyle = '#b8860b';
    ctx.fill();
    ctx.beginPath();
    ctx.arc(CX, CY, 10, 0, 2 * Math.PI);
    ctx.fillStyle = '#2c1810';
    ctx.fill();

    // Indicator triangle at top (points down into wheel)
    ctx.beginPath();
    ctx.moveTo(CX,     CY - RO - 1);
    ctx.lineTo(CX - 7, CY - RO - 13);
    ctx.lineTo(CX + 7, CY - RO - 13);
    ctx.closePath();
    ctx.fillStyle = '#FFD700';
    ctx.fill();

    // Ball
    var bx = CX + ws.ballRadius * Math.cos(ws.ballAngle);
    var by = CY + ws.ballRadius * Math.sin(ws.ballAngle);
    ctx.save();
    ctx.shadowColor = 'rgba(0,0,0,0.6)';
    ctx.shadowBlur = 5;
    ctx.beginPath();
    ctx.arc(bx, by, 6, 0, 2 * Math.PI);
    var ballGrad = ctx.createRadialGradient(bx - 2, by - 2, 1, bx, by, 6);
    ballGrad.addColorStop(0, '#ffffff');
    ballGrad.addColorStop(1, '#cccccc');
    ctx.fillStyle = ballGrad;
    ctx.fill();
    ctx.restore();
}

if (phase === 'spinning' && spinResult !== null) {
    var resultIdx = WHEEL.indexOf(spinResult.number);
    // Target: result pocket aligned with indicator at top (-PI/2)
    var baseTarget = -Math.PI / 2 - resultIdx * SLOT;
    var minTarget  = ws.angle + 5 * 2 * Math.PI;
    while (baseTarget < minTarget) baseTarget += 2 * Math.PI;
    var targetAngle = baseTarget;

    var startWheelAngle = ws.angle;
    var startBallAngle  = ws.ballAngle;
    var DURATION = 1300;
    var startTime = null;
    var active = true;
    var lastOrbitAngle = startBallAngle;

    window._rl_wheel_cancel = function() { active = false; };

    function easeOut(t) { return 1 - Math.pow(1 - t, 4); }

    function animate(ts) {
        if (!active) return;
        if (!startTime) startTime = ts;
        var t = Math.min((ts - startTime) / DURATION, 1);
        var e = easeOut(t);

        ws.angle = startWheelAngle + (targetAngle - startWheelAngle) * e;

        // Ball orbits counter-clockwise, 2.5x wheel speed; drops into pocket in last 15%
        if (t < 0.85) {
            ws.ballAngle  = startBallAngle - 2.5 * (ws.angle - startWheelAngle);
            ws.ballRadius = BALL_R;
            lastOrbitAngle = ws.ballAngle;
        } else {
            var dropT = (t - 0.85) / 0.15;
            ws.ballAngle  = lastOrbitAngle + (-Math.PI / 2 - lastOrbitAngle) * dropT;
            ws.ballRadius = BALL_R - (BALL_R - POCKET_R) * dropT;
        }

        draw();

        if (t < 1) {
            requestAnimationFrame(animate);
        } else {
            active = false;
            ws.angle      = targetAngle;
            ws.ballAngle  = -Math.PI / 2;
            ws.ballRadius = POCKET_R;
            draw();
        }
    }

    requestAnimationFrame(animate);

} else {
    // result or betting: static draw
    if (phase === 'result' && result !== null) {
        ws.ballAngle  = -Math.PI / 2;
        ws.ballRadius = POCKET_R;
    } else if (phase === 'betting') {
        ws.ballRadius = BALL_R;
    }
    draw();
